// this node handles a request to charge
// Variables
let data = context.global.data;
let batt_soc = data["batt_soc"];
let charge_state = data["charge_state"];

//Globals
let max_soc = context.global.max_soc;
let idle_rate = context.global.idle_rate;
let charge_rate = context.global.charge_rate;
msg.batt_mode = msg.payload // either Charge or IQ Smart Mode
let adjusted = context.global.setpoint_adjusted || false;
let max_phase = context.global.max_phase_power;
let p1 = data["grid_l1_w"] || 0;
let p2 = data["grid_l2_w"] || 0;
let p3 = data["grid_l3_w"] || 0;
let sp = 0;
let num_multi = context.global.number_of_multiplus;
//node.warn("P1, P2, P3 " + p1 + " " + p2 + " " + p3)
//node.warn("sp " + sp)
//node.warn("In Power Monitor, adjusted is "+adjusted)

let txt="";

// charge is requested, only charge if not at max_soc
if (batt_soc < max_soc) {
    // check what power we can start at in case something else is drawing power
    let highest_phase_power = Math.max(p1,p2,p3);           // phase with the highest load
	let delta = highest_phase_power - max_phase;            // how much over the max for the phase
	sp = Math.ceil(sp - (delta * num_multi));           // lower for each inverter as one setpoint for all
	if (sp < charge_rate) {
	    //node.warn("Charge: Diff is "+delta+" for a new setpoint of "+sp);
	    if (sp < 0) {                                        // lets not switch to a discharge state
            node.warn("Charge: no charge power left so idle until we can increase");
            // prevent a discharge so go to idle
	        sp = idle_rate;
	    }
	    else {
	        node.warn("Charge: adapt to available power: "+sp);
	    }
	    context.global.setpoint_adjusted = true;
	    context.global.data["original_setpoint"] = charge_rate;
        msg.payload = sp;
	}
	else {
	    msg.payload = charge_rate;
	    context.global.setpoint_adjusted = false;
	}
    node.warn("Charge: setting setpoint now to "+msg.payload);
    txt="Victron: Charge requested by "+msg.payload+", starting at "+charge_rate;
    node.warn(txt);
}
else { 
    // batt == max_soc
    if (charge_state == 'Float') {
        txt="Victron: Battery already full, switching to idle"
        node.warn(txt)
        if (msg.payload != "IQ Smart Mode") {
            msg.batt_mode = "Idle"
        }
        msg.payload = idle_rate;
    }
    else {
        msg.payload = charge_rate;
        txt="Victron: Charge requested by "+msg.payload+", continuing at "+charge_rate;
        node.warn(txt);
        context.global.setpoint_adjusted = false;
    }
}
msg.inform_domo = true;
msg.domo_msg = txt;
return msg;

